 * @description 「보고서확장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.edit_btn_onclick = function(e){
    try {
        editorSizeChange()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00004.edit_btn_onclick' }); }
};

